# 【算法思路】用列表尾部表示最近使用、头部表示最久未用，模拟页面置换并统计命中率。
# 按页请求序列执行 LRU 命中提升与满容量头部淘汰
def simulate_page_cache(page_requests: list, capacity: int) -> dict:
    if capacity <= 0:
        return {"hits": 0, "misses": len(page_requests), "hit_rate": 0.0}

    cache = []
    hits = 0
    misses = 0

    for page in page_requests:
        if page in cache:
            hits += 1
            cache.remove(page)
            cache.append(page)
        else:
            misses += 1
            if len(cache) >= capacity:
                cache.pop(0)
            cache.append(page)

    total = hits + misses
    return {"hits": hits, "misses": misses, "hit_rate": round(hits / total, 4) if total else 0.0}

