import math

# 分别计算所需 inode 与 block 并判定容量与瓶颈
def plan_small_file_storage(file_count: int, avg_file_size: int, block_size: int, total_blocks: int, total_inodes: int) -> dict:
    if block_size <= 0:
        raise ValueError("block_size must be positive")
    needed_blocks = file_count * math.ceil(avg_file_size / block_size)
    needed_inodes = file_count

    if needed_inodes > total_inodes:
        return {"fits": False, "bottleneck": "inode"}
    if needed_blocks > total_blocks:
        return {"fits": False, "bottleneck": "block"}
    return {"fits": True, "bottleneck": "none"}

# 【算法思路】将三位八进制权限按位拆解，结合文件类型检测组/其他写权限与不当可执行位。
# 解析 rwx 比特位并依据 config/script 类型输出风险标签
def audit_permission(octal: str, file_type: str) -> list:
    if len(octal) != 3 or not octal.isdigit():
        raise ValueError("octal permission must look like 644")

    owner, group, others = [int(ch) for ch in octal]
    risks = []

    if group & 2:
        risks.append("group_writable")
    if others & 2:
        risks.append("others_writable")

    if file_type == "config" and owner & 1:
        risks.append("config_executable")
    if file_type == "script" and not (owner & 1):
        risks.append("owner_not_executable")

    return risks

