def first_fit(free_list, size):
    for i, (start, end) in enumerate(free_list):
        if end-start >= size:
            return i, start, start+size
    return -1,0,0
# 筛选满足大小且碎片最小的空闲分区
def best_fit(free_list, size):
    best_i, best_sz = -1, float('inf')
    for i, (start, end) in enumerate(free_list):
        sz = end-start
        if sz >= size and sz < best_sz:
            best_i, best_sz = i, sz
    if best_i>=0: return best_i, free_list[best_i][0], free_list[best_i][0]+size
    return -1,0,0

