def simulate_squash(commits, target_count):
    if len(commits) <= target_count:
        return commits
    result = []
    for i, c in enumerate(commits):
        if i == 0:
            result.append(c)
        elif i < len(commits) - (target_count-1):
            result[-1]['message'] += '; ' + c['message']
        else:
            result.append(c)
    return result

